<script setup lang="ts">import {computed} from "vue";import {RefreshCw,RotateCw} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ValidationMessage from "@/components/zs/ValidationMessage.vue";import {useAsyncData} from "@/composables/useAsyncData";import {platformRepository} from "@/services/platform/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta('System Health','Application readiness and safe failed-job operations.');const company=useCompanyStore(),health=useAsyncData(()=>platformRepository.ready()),jobs=useAsyncData(()=>platformRepository.failedJobs(company.activeCompanyId),{watch:[()=>company.activeCompanyId]}),rows=computed(()=>jobs.data.value?.data??[]),columns:Column[]=[{key:'type',header:'Job'},{key:'queue',header:'Queue'},{key:'failed_at',header:'Failed'},{key:'exception_summary',header:'Exception'},{key:'actions',header:''}];async function retry(uuid:string){await platformRepository.retryJob(company.activeCompanyId,uuid);showToast('Job queued for retry');await jobs.refresh()}</script>
<template><AppShell><PageHeader title="System Health" description="Dependency readiness without exposing infrastructure credentials"><template #actions><ZButton variant="outline" @click="health.refresh();jobs.refresh()"><RefreshCw class="size-4"/>Refresh</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><StatCard v-for="(passing,name) in health.data.value?.checks??{}" :key="name" :label="name" :value="passing?'Ready':'Unavailable'" :tone="passing?'success':'danger'"/></div><ValidationMessage :message="health.error.value?.message??jobs.error.value?.message"/><Panel title="Failed jobs" description="Payload contents are intentionally withheld"><DataTable :columns="columns" :rows="rows" :min-width="900"><template #type="{row}"><span class="font-medium text-content">{{row.type}}</span></template><template #queue="{row}"><StatusBadge :status="row.queue"/></template><template #failed_at="{row}">{{new Date(row.failed_at).toLocaleString()}}</template><template #exception_summary="{row}"><span class="block max-w-md truncate text-xs text-content-secondary">{{row.exception_summary}}</span></template><template #actions="{row}"><ZButton v-if="company.hasPermission('platform.jobs.manage')" variant="ghost" @click="retry(row.uuid)"><RotateCw class="size-4"/>Retry</ZButton></template></DataTable></Panel></AppShell></template>
